<script setup lang="ts">
import { matchDate } from '../services/format';
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { api, errorMessage } from '../services/api';
import { useClub } from '../stores/club';
import StateNotice from '../components/StateNotice.vue';
const route = useRoute(), club = useClub(); const match = ref<any>(), error = ref(''), message = ref(''), busy = ref(false), teamId = ref(''), squad = ref<any[]>([]), entries = ref<any[]>([]), formation = ref('4-3-3'), selectedPlayer = ref('');
const homeScore = ref<number | null>(null), awayScore = ref<number | null>(null), status = ref('SCHEDULED'), eventType = ref('GOAL'), minute = ref(0), playerId = ref(''), relatedPlayerId = ref('');
const params = computed(() => typeof route.query.organizationId === 'string' ? { organizationId: route.query.organizationId } : {});
const canEdit = computed(() => !!params.value.organizationId && params.value.organizationId === club.selectedId && club.can('sport:write'));
async function load() { busy.value = true; error.value = ''; try { match.value = (await api.get(`/matches/${route.params.id}`, { params: params.value })).data; homeScore.value = match.value.homeScore; awayScore.value = match.value.awayScore; status.value = match.value.status; if (!teamId.value) teamId.value = match.value.homeTeamId; await loadTeam(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function loadTeam() { if (!match.value || !teamId.value) return; try { squad.value = (await api.get('/players', { params: { ...params.value, teamId: teamId.value, seasonId: match.value.seasonId, limit: 100 } })).data.items; entries.value = match.value.appearances.filter((p: any) => p.teamId === teamId.value).map((p: any) => ({ playerId: p.playerId, teamId: p.teamId, minutes: p.minutes, starter: p.starter, ...(p.shirtNumber ? { shirtNumber: p.shirtNumber } : {}) })); formation.value = match.value.lineups.find((l: any) => l.teamId === teamId.value)?.formation ?? '4-3-3'; selectedPlayer.value = ''; playerId.value = ''; relatedPlayerId.value = ''; } catch (e) { error.value = errorMessage(e); } }
function addPlayer() { if (selectedPlayer.value && !entries.value.some(e => e.playerId === selectedPlayer.value)) entries.value.push({ playerId: selectedPlayer.value, teamId: teamId.value, starter: false, minutes: 0 }); selectedPlayer.value = ''; }
async function mutate(path: string, method: 'patch' | 'put' | 'post' | 'delete', body?: any) { busy.value = true; error.value = ''; try { await api.request({ url: path, method, data: body, params: params.value }); message.value = 'Partido actualizado'; await load(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load); watch(teamId, loadTeam);
</script>
<template><section><button class="button subtle back" @click="$router.back()"><i aria-hidden="true" class="pi pi-arrow-left" /> Volver</button><StateNotice :loading="busy" :error="error" @retry="load" /><template v-if="match && !busy"><div class="match-detail panel"><span class="eyebrow">{{ match.season.name }} · {{ matchDate(match, true) + (match.kickoffTimezoneKnown === false ? ' | hora del dataset, zona desconocida' : '') }}</span><div class="big-score"><div><span class="team-badge">{{ match.homeTeam.name.slice(0, 2).toUpperCase() }}</span><h2>{{ match.homeTeam.name }}</h2></div><strong>{{ match.homeScore ?? '–' }} <span>:</span> {{ match.awayScore ?? '–' }}</strong><div><span class="team-badge away">{{ match.awayTeam.name.slice(0, 2).toUpperCase() }}</span><h2>{{ match.awayTeam.name }}</h2></div></div><span class="pill">{{ match.status }}</span><p v-if="match.isDemo" class="muted">Partido ficticio · DEMO</p></div><p v-if="message" class="alert success">{{ message }}</p><section v-if="canEdit" class="panel section-gap"><h2>Resultado oficial</h2><form class="inline-form" @submit.prevent="mutate(`/matches/${match.id}/result`, 'patch', { status, homeScore, awayScore })"><label>Estado<select v-model="status"><option>SCHEDULED</option><option>LIVE</option><option>FINISHED</option></select></label><label>Local<input v-model.number="homeScore" type="number" min="0" max="99" required></label><label>Visitante<input v-model.number="awayScore" type="number" min="0" max="99" required></label><button class="button primary">Guardar resultado</button></form><p class="chart-footnote">El marcador se registra por separado. Añade los eventos y minutos para alimentar las estadísticas individuales.</p></section><div class="dashboard-grid section-gap"><section class="panel"><h2>Eventos del partido</h2><div v-for="e in match.events" :key="e.id" class="event-row"><strong class="accent">{{ e.minute }}′</strong><div><span>{{ { GOAL: 'Gol', OWN_GOAL: 'Autogol', YELLOW_CARD: 'Amarilla', RED_CARD: 'Roja', SUBSTITUTION: 'Sustitución' }[e.type as string] }}</span><h3>{{ e.player.name }}</h3><p v-if="e.relatedPlayer">Entra {{ e.relatedPlayer.name }}</p></div><button v-if="canEdit" class="icon-button" aria-label="Eliminar evento" @click="mutate(`/match-events/${e.id}`, 'delete')"><i aria-hidden="true" class="pi pi-times" /></button></div><StateNotice :empty="!match.events.length" /></section><section class="panel"><h2>Participaciones registradas</h2><div v-for="p in match.appearances" :key="p.id" class="roster-row"><RouterLink :to="{ path: `/players/${p.playerId}`, query: params }">{{ p.player.name }}</RouterLink><span>{{ p.starter ? 'Titular' : 'Suplente' }} · {{ p.minutes }} min</span></div><StateNotice :empty="!match.appearances.length" /></section></div><section v-if="canEdit" class="panel section-gap"><h2>Convocatoria y alineación</h2><div class="filter-bar"><select v-model="teamId" aria-label="Equipo"><option :value="match.homeTeamId">{{ match.homeTeam.name }}</option><option :value="match.awayTeamId">{{ match.awayTeam.name }}</option></select><label>Formación<input v-model="formation" placeholder="4-3-3"></label></div><form class="inline-form" @submit.prevent="addPlayer"><select v-model="selectedPlayer" required aria-label="Añadir jugador"><option value="">Jugador de la plantilla</option><option v-for="p in squad.filter(p => !entries.some(e => e.playerId === p.id))" :key="p.id" :value="p.id">{{ p.name }}</option></select><button class="button subtle">Añadir a convocatoria</button></form><form class="section-gap" @submit.prevent="mutate(`/matches/${match.id}/lineup`, 'put', { teamId, formation, appearances: entries })"><div v-for="(e, i) in entries" :key="e.playerId" class="lineup-row"><strong>{{ squad.find(p => p.id === e.playerId)?.name ?? match.appearances.find((p: any) => p.playerId === e.playerId)?.player.name }}</strong><label class="toggle"><input v-model="e.starter" type="checkbox"> Titular</label><label>Minutos<input v-model.number="e.minutes" required type="number" min="0" max="120"></label><button type="button" class="icon-button" aria-label="Quitar convocado" @click="entries.splice(i, 1)"><i aria-hidden="true" class="pi pi-times" /></button></div><button class="button primary section-gap">Guardar convocatoria y minutos</button></form><h3 class="section-gap">Añadir evento</h3><form class="inline-form" @submit.prevent="mutate('/match-events', 'post', { matchId: match.id, teamId, playerId, minute, type: eventType, ...(eventType === 'SUBSTITUTION' ? { relatedPlayerId } : {}) })"><select v-model="eventType" aria-label="Tipo de evento"><option v-for="t in [['GOAL', 'Gol'], ['OWN_GOAL', 'Autogol'], ['YELLOW_CARD', 'Amarilla'], ['RED_CARD', 'Roja'], ['SUBSTITUTION', 'Sustitución']]" :key="t[0]" :value="t[0]">{{ t[1] }}</option></select><select v-model="playerId" required aria-label="Jugador del evento"><option value="">Jugador / sale</option><option v-for="p in match.appearances.filter((p: any) => p.teamId === teamId)" :key="p.id" :value="p.playerId">{{ p.player.name }}</option></select><select v-if="eventType === 'SUBSTITUTION'" v-model="relatedPlayerId" required aria-label="Jugador entrante"><option value="">Entra</option><option v-for="p in match.appearances.filter((p: any) => p.teamId === teamId && p.playerId !== playerId)" :key="p.id" :value="p.playerId">{{ p.player.name }}</option></select><label>Minuto<input v-model.number="minute" required type="number" min="0" max="130"></label><button class="button primary">Registrar evento</button></form></section></template></section></template>
